 p=('../persistent/index_data/' if macro else '../persistent/stock_data/')+sym+'.csv'
 d=pd.read_csv(p,parse_dates=['date']).set_index('date'); return d.loc[:cut,'close'].pct_change()
R=pd.concat({s:load(s) for s in U},axis=1); m=load('DXY',True)
# factor: negative rolling beta to DXY, defensive when asset falls as dollar rises
