ret=p.pct_change()
def run(w):
 fac=-ret.rolling(w,min_periods=max(10,w//2)).std()
 ics=[]; turns=[]; ns=[]
 for i in range(w,len(p)-1):
  x=fac.iloc[i]; y=ret.iloc[i+1]; z=pd.concat([x,y],axis=1).dropna()
  if len(z)>=8:
   ics.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman')); ns.append(len(z))
