 print(label,len(a),np.nanmean(a),np.nanmean(a)/np.nanstd(a,ddof=1) if len(a)>1 else np.nan)
# horizon decay for 20d factor
fac=-ret.rolling(20,min_periods=10).std()
for h in [1,5,10]:
 a=[]
 for i in range(20,len(p)-h):
