)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Current Screener ensemble; five active factors, exact normalized weights.
FACTOR_WEIGHTS = {"clv": 0.3075, "peer": 0.2362, "rev5": 0.1826,
                  "mom20": 0.1797, "rev3": 0.0940}
MIN_W, MAX_W, CADENCE = 0.015, 0.16, 10
last_decision = None


def rank_map(values):
    out = {s: 0.5 for s in UNIVERSE}
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    if len(valid) > 1:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1.0) / len(valid)
    return out


def capped_simplex(raw):
    # Floors/caps preserve diversification in the 15-name cross-asset universe.
    w = {s: min(MAX_W, max(MIN_W, float(raw.get(s, MIN_W)))) for s in UNIVERSE}
    for _ in range(200):
        err = 1.0 - sum(w.values())
        if abs(err) < 1e-10:
            break
        free = [s for s in UNIVERSE if MIN_W + 1e-9 < w[s] < MAX_W - 1e-9]
        if not free:
            break
        for s in free:
            w[s] = min(MAX_W, max(MIN_W, w[s] + err / len(free)))
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
