import pandas as pd, numpy as np, os
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in U:
 x=pd.read_csv('../persistent/stock_data/'+s+'.csv'); x['date']=pd.to_datetime(x['date']); x=x.sort_values('date').set_index('date'); D[s]=x
# volatility compression: negative log ratio of recent 5d vol to prior 20d vol, all completed at t
rets={s:D[s]['close'].pct_change() for s in U}
common=sorted(set.intersection(*[set(x.index) for x in D.values()]))
for h in [1,5,10]:
  ics=[]; ns=[]; turnover=[]; prev=None
  for i in range(30,len(common)-h):
    dt=common[i]; f={}; y={}
    for s in U:
      r=rets[s].reindex(common[:i+1])
      if len(r.dropna())<25: continue
      v5=r.iloc[-5:].std(); v20=r.iloc[-25:-5].std()
      if pd.notna(v5) and pd.notna(v20) and v20>0:
        f[s]=-np.log((v5+1e-10)/(v20+1e-10))
        y[s]=D[s]['close'].pct_change(h).shift(-h).reindex([dt]).iloc[0] if dt in D[s].index else np.nan
    z={s:v for s,v in y.items() if pd.notna(v) and s in f}
    if len(z)>=8:
      a=np.array([f[s] for s in z]); b=np.array([z[s] for s in z]); ics.append(spearmanr(a,b).statistic); ns.append(len(z))
      ranks=pd.Series(a,index=list(z)).rank().values
      if prev is not None: turnover.append(np.mean(ranks!=prev))
      prev=ranks
  q=np.array(ics); print('h',h,'dates',len(q),'avg_names',round(np.mean(ns),2),'IC',round(q.mean(),6),'ICIR',round(q.mean()/q.std(ddof=1),6),'hit',round(np.mean(q>0),4),'turn',round(np.mean(turnover),4))
  for lo,hi in [(0,758),(758,1274),(1274,9999)]:
    z=q[lo:hi]
    if len(z): print(' regime',len(z),round(z.mean(),6),round(z.mean()/z.std(ddof=1),6))
print('coverage',len(common))

